diff --git a/package/CompressLazy.roc b/package/CompressLazy.roc
index fc4750c..e86b076 100644
--- a/package/CompressLazy.roc
+++ b/package/CompressLazy.roc
@@ -667,14 +667,19 @@ CompressLazy := [].{
 							$nh4 = Matchfinder.lz_hash(repeat_next, HcMatchfinder.hash4_order)
 						} else {
 						}
-						while $skip_at < skip_limit {
-							skip_node = $skip_node.to_u16_wrap()
+						chain_limit = skip_limit.minus_wrap($base)
+						if $base > $skip_at or $skip_at > skip_limit or chain_limit > Matchfinder.window_size or $base + chain_limit + 4 > List.len(input) {
+							crash "skip chain outside window"
+						} else {}
+						var $chain_at = $skip_at.minus_wrap($base)
+						while $chain_at < chain_limit {
+							skip_node = $chain_at.plus_wrap(Matchfinder.node_bias).to_u16_wrap()
 							prev_head = List.get($mf, HcMatchfinder.greedy_layout.hash4_base.plus_wrap($nh4)) ?? 0
 							$mf = match List.set($mf, HcMatchfinder.greedy_layout.hash3_base.plus_wrap($nh3), skip_node) {
 								Ok(next) => next
 								Err(_) => crash "CompressLazy.compress_greedy: mf index out of bounds"
 							}
-							$mf = match List.set($mf, HcMatchfinder.greedy_layout.next_base.plus_wrap($skip_node.bitwise_and(32767)), prev_head) {
+							$mf = match List.set($mf, HcMatchfinder.greedy_layout.next_base.plus_wrap($chain_at), prev_head) {
 								Ok(next) => next
 								Err(_) => crash "CompressLazy.compress_greedy: mf index out of bounds"
 							}
@@ -682,9 +687,8 @@ CompressLazy := [].{
 								Ok(next) => next
 								Err(_) => crash "CompressLazy.compress_greedy: mf index out of bounds"
 							}
-							$skip_at = $skip_at.plus_wrap(1)
-							$skip_node = $skip_node.plus_wrap(1)
-							skip_hashseq = U32.from_le_bytes(input, $skip_at) ?? 0
+							$chain_at = $chain_at.plus_wrap(1)
+							skip_hashseq = U32.from_le_bytes(input, $base.plus_wrap($chain_at)) ?? 0
 							$nh3 = Matchfinder.lz_hash(skip_hashseq.bitwise_and(0xFFFFFF), HcMatchfinder.hash3_order)
 							$nh4 = Matchfinder.lz_hash(skip_hashseq, HcMatchfinder.hash4_order)
 						}
@@ -1611,15 +1615,19 @@ CompressLazy := [].{
 									var $skip_at = $in_next
 									# The node is carried already biased. The bias is one window, so masking
 									# the biased node gives the position's chain slot as well.
-									var $skip_node = $skip_at.minus_wrap($base).plus_wrap(Matchfinder.node_bias)
-									while $skip_at < skip_limit {
-										skip_node = $skip_node.to_u16_wrap()
+									chain_limit = skip_limit.minus_wrap($base)
+									if $base > $skip_at or $skip_at > skip_limit or chain_limit > Matchfinder.window_size or $base + chain_limit + 4 > List.len(input) {
+										crash "skip chain outside window"
+									} else {}
+									var $chain_at = $skip_at.minus_wrap($base)
+									while $chain_at < chain_limit {
+										skip_node = $chain_at.plus_wrap(Matchfinder.node_bias).to_u16_wrap()
 										prev_head = List.get($mf, HcMatchfinder.hash4_base.plus_wrap($nh4)) ?? 0
 										$mf = match List.set($mf, HcMatchfinder.hash3_base.plus_wrap($nh3), skip_node) {
 											Ok(next) => next
 											Err(_) => crash "CompressLazy.compress: mf index out of bounds"
 										}
-										$mf = match List.set($mf, HcMatchfinder.next_base.plus_wrap($skip_node.bitwise_and(32767)), prev_head) {
+										$mf = match List.set($mf, HcMatchfinder.next_base.plus_wrap($chain_at), prev_head) {
 											Ok(next) => next
 											Err(_) => crash "CompressLazy.compress: mf index out of bounds"
 										}
@@ -1627,9 +1635,8 @@ CompressLazy := [].{
 											Ok(next) => next
 											Err(_) => crash "CompressLazy.compress: mf index out of bounds"
 										}
-										$skip_at = $skip_at.plus_wrap(1)
-										$skip_node = $skip_node.plus_wrap(1)
-										skip_hashseq = U32.from_le_bytes(input, $skip_at) ?? 0
+										$chain_at = $chain_at.plus_wrap(1)
+										skip_hashseq = U32.from_le_bytes(input, $base.plus_wrap($chain_at)) ?? 0
 										$nh3 = Matchfinder.lz_hash(skip_hashseq.bitwise_and(0xFFFFFF), HcMatchfinder.hash3_order)
 										$nh4 = Matchfinder.lz_hash(skip_hashseq, HcMatchfinder.hash4_order)
 									}
